.hero-about-name {
    font-size: var(--font-5xl);
    font-weight: 800;
    color: var(--text-primary);
    margin-bottom: var(--spacing-sm);
}

.hero-about-title {
    font-size: var(--font-xl);
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
}

.hero-about-bio {
    max-width: 600px;
    font-size: var(--font-lg);
    color: var(--text-secondary);
    margin-bottom: var(--spacing-xl);
    line-height: 1.8;
}

.hero-about-social {
    display: flex;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-xl);
}

.social-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    background-color: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    color: var(--text-secondary);
    font-size: var(--font-lg);
    text-decoration: none;
    transition: all var(--transition);
}

.social-btn:hover {
    background-color: var(--primary);
    border-color: var(--primary);
    color: white;
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.hero-about-cta {
    display: flex;
    gap: var(--spacing-md);
}

/* ============================================
   技能区域
   ============================================ */
.skills-container {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xl);
}

.skill-category {
    background-color: var(--bg-card);
    border-radius: var(--radius-xl);
    padding: var(--spacing-xl);
    border: 1px solid var(--border-light);
}

.skill-category-title {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-lg);
}

.skill-category-title i {
    color: var(--primary);
}

.skills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
}

.skill-item {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.skill-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    border-radius: var(--radius-lg);
    color: var(--primary);
    font-size: 1.5rem;
}

[data-theme="dark"] .skill-icon {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
}

.skill-name {
    font-size: var(--font-sm);
    font-weight: 600;
    color: var(--text-primary);
}

.skill-level {
    height: 6px;
    background-color: var(--bg-tertiary);
    border-radius: var(--radius-full);
    overflow: hidden;
}

.skill-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--primary), var(--primary-dark));
    border-radius: var(--radius-full);
    transition: width 1s ease-out;
}

/* ============================================
   时间线
   ============================================ */
.timeline {
    position: relative;
    max-width: 800px;
    margin: 0 auto;
}

.timeline::before {
    content: '';
    position: absolute;
    left: 24px;
    top: 0;
    bottom: 0;
    width: 2px;
    background: linear-gradient(180deg, var(--primary), var(--primary-light));
}

.timeline-item {
    position: relative;
    padding-left: 60px;
    padding-bottom: var(--spacing-xl);
}

.timeline-marker {
    position: absolute;
    left: 12px;
    top: 0;
    width: 26px;
    height: 26px;
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    border: 4px solid var(--bg-primary);
    border-radius: var(--radius-full);
    box-shadow: var(--shadow-md);
}

.timeline-content {
    background-color: var(--bg-card);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    border: 1px solid var(--border-light);
    transition: all var(--transition);
}

.timeline-content:hover {
    box-shadow: var(--shadow-lg);
    transform: translateX(4px);
}

.timeline-date {
    display: inline-block;
    padding: var(--spacing-xs) var(--spacing-sm);
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    color: var(--primary-600);
    font-size: var(--font-xs);
    font-weight: 600;
    border-radius: var(--radius-sm);
    margin-bottom: var(--spacing-sm);
}

[data-theme="dark"] .timeline-date {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
    color: var(--primary-200);
}

.timeline-title {
    font-size: var(--font-xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-xs);
}

.timeline-company {
    font-size: var(--font-sm);
    color: var(--primary);
    margin-bottom: var(--spacing-sm);
}

.timeline-description {
    font-size: var(--font-sm);
    color: var(--text-secondary);
    line-height: 1.7;
    margin-bottom: var(--spacing-md);
}

.timeline-tags {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-xs);
}

/* ============================================
   成就卡片
   ============================================ */
.achievements-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.achievement-card {
    background-color: var(--bg-card);
    border-radius: var(--radius-xl);
    padding: var(--spacing-xl);
    border: 1px solid var(--border-light);
    text-align: center;
    transition: all var(--transition);
}

.achievement-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-xl);
}

.achievement-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 70px;
    height: 70px;
    margin: 0 auto var(--spacing-md);
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    border-radius: var(--radius-xl);
    color: var(--primary);
    font-size: 2rem;
}

[data-theme="dark"] .achievement-icon {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
}

.achievement-title {
    font-size: var(--font-xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-sm);
}

.achievement-description {
    font-size: var(--font-sm);
    color: var(--text-secondary);
    line-height: 1.6;
    margin-bottom: var(--spacing-md);
}

.achievement-stats {
    display: flex;
    justify-content: center;
    gap: var(--spacing-md);
    flex-wrap: wrap;
}

.achievement-stats span {
    display: flex;
    align-items: center;
    gap: var(--spacing-xs);
    font-size: var(--font-xs);
    color: var(--text-tertiary);
}

.achievement-stats i {
    color: var(--primary);
}

/* ============================================
   兴趣爱好
   ============================================ */
.interests-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-md);
}

.interest-card {
    background-color: var(--bg-card);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    border: 1px solid var(--border-light);
    text-align: center;
    transition: all var(--transition);
}

.interest-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
    border-color: var(--primary-200);
}

.interest-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 60px;
    height: 60px;
    margin: 0 auto var(--spacing-md);
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    border-radius: var(--radius-xl);
    color: var(--primary);
    font-size: 1.5rem;
}

[data-theme="dark"] .interest-icon {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
}

.interest-name {
    font-size: var(--font-lg);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-xs);
}

.interest-description {
    font-size: var(--font-sm);
    color: var(--text-secondary);
    line-height: 1.5;
}

/* ============================================
   联系区域
   ============================================ */
.contact-card {
    max-width: 600px;
    margin: 0 auto;
    padding: var(--spacing-2xl);
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    border-radius: var(--radius-2xl);
    text-align: center;
}

[data-theme="dark"] .contact-card {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
}

.contact-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 80px;
    height: 80px;
    margin: 0 auto var(--spacing-lg);
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    border-radius: var(--radius-full);
    color: white;
    font-size: 2rem;
}

.contact-title {
    font-size: var(--font-3xl);
    font-weight: 800;
    color: var(--text-primary);
    margin-bottom: var(--spacing-sm);
}

.contact-description {
    font-size: var(--font-lg);
    color: var(--text-secondary);
    margin-bottom: var(--spacing-xl);
}

.contact-info {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    align-items: center;
}

.contact-item {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    padding: var(--spacing-sm) var(--spacing-md);
    background-color: var(--bg-card);
    border-radius: var(--radius);
    color: var(--text-primary);
    text-decoration: none;
    transition: all var(--transition);
}

.contact-item:hover {
    background-color: var(--primary);
    color: white;
    transform: translateX(4px);
}

.contact-item i {
    color: var(--primary);
}

.contact-item:hover i {
    color: white;
}

/* ============================================
   响应式设计
   ============================================ */
@media (max-width: 1024px) {
    .hero-content {
        max-width: 100%;
    }

    .hero-actions {
        flex-direction: column;
    }

    .hero-actions .btn {
        width: 100%;
        justify-content: center;
    }

    .article-card.featured {
        grid-template-columns: 1fr;
    }

    .article-card.featured .article-image {
        height: 200px;
        min-height: 200px;
    }

    .article-item {
        grid-template-columns: 1fr;
    }

    .article-item-image {
        height: 200px;
    }
}

@media (max-width: 768px) {
    .nav-menu {
        position: fixed;
        top: 70px;
        left: 0;
        right: 0;
        flex-direction: column;
        gap: 0;
        background-color: var(--bg-primary);
        border-bottom: 1px solid var(--border);
        transform: translateY(-100%);
        opacity: 0;
        visibility: hidden;
        transition: all var(--transition);
    }

    .nav-menu.open {
        transform: translateY(0);
        opacity: 1;
        visibility: visible;
    }

    .nav-menu li {
        width: 100%;
        border-bottom: 1px solid var(--border-light);
    }

    .nav-menu a {
        display: block;
        padding: var(--spacing-md) var(--spacing-lg);
    }

    .nav-menu a::after {
        display: none;
    }

    .mobile-menu-btn {
        display: flex;
    }

    .hero-illustration {
        width: 300px;
        height: 300px;
    }

    .illustration-circle {
        width: 200px;
        height: 200px;
    }

    .illustration-icon {
        width: 60px;
        height: 60px;
        font-size: 1.5rem;
    }

    .hero-stats {
        flex-direction: column;
        gap: var(--spacing);
    }

    .stat-divider {
        width: 40px;
        height: 1px;
    }

    .articles-grid {
        grid-template-columns: 1fr;
    }

    .footer-content {
        grid-template-columns: 1fr;
    }

    .footer-links {
        grid-template-columns: 1fr;
    }

    .category-item-header {
        flex-direction: column;
        text-align: center;
    }

    .timeline::before {
        left: 12px;
    }

    .timeline-item {
        padding-left: 40px;
    }

    .timeline-marker {
        left: 0;
        width: 24px;
        height: 24px;
    }

    .skills-grid {
        grid-template-columns: 1fr;
    }

    .hero-about-cta {
        flex-direction: column;
    }

    .hero-about-cta .btn {
        width: 100%;
        justify-content: center;
    }

    .filters-container {
        gap: var(--spacing-md);
    }

    .filter-tabs {
        gap: var(--spacing-xs);
    }

    .filter-tab {
        font-size: var(--font-xs);
        padding: var(--spacing-xs) var(--spacing-sm);
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 var(--spacing);
    }

    .hero-title {
        font-size: var(--font-3xl);
    }

    .hero-description {
        font-size: var(--font-base);
    }

    .section-title {
        font-size: var(--font-2xl);
    }

    .page-title {
        font-size: var(--font-3xl);
    }

    .hero-stats {
        padding: var(--spacing-md);
    }

    .stat-number {
        font-size: var(--font-xl);
    }

    .newsletter-card,
    .contact-card {
        padding: var(--spacing-lg);
    }

    .newsletter-form .form-group {
        flex-direction: column;
    }

    .newsletter-form button {
        width: 100%;
    }

    .back-to-top {
        width: 44px;
        height: 44px;
        bottom: var(--spacing-md);
        right: var(--spacing-md);
    }
}

/* ============================================
   打印样式
   ============================================ */
@media print {
    .navbar,
    .hero-actions,
    .hero-stats,
    .back-to-top,
    .footer,
    .newsletter-card,
    .contact-card {
        display: none !important;
    }

    body {
        font-size: 12pt;
        color: #000;
        background: white;
    }

    a {
        text-decoration: underline;
        color: #000;
    }
}

/* ============================================
   辅助功能
   ============================================ */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    .scroll-behavior {
        scroll-behavior: auto;
    }
}

/* 焦点样式 */
button:focus-visible,
a:focus-visible,
input:focus-visible {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
}

/* 选中文本样式 */
::selection {
    background-color: var(--primary-200);
    color: var(--text-primary);
}

[data-theme="dark"] ::selection {
    background-color: var(--primary-800);
}"}

