    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.article-tags {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.tag {
    padding: var(--spacing-xs) var(--spacing-sm);
    background-color: var(--bg-tertiary);
    color: var(--text-tertiary);
    font-size: var(--font-xs);
    font-weight: 500;
    border-radius: var(--radius-sm);
    transition: all var(--transition);
}

.tag:hover {
    background-color: var(--primary-100);
    color: var(--primary-600);
}

.article-item-footer {
    margin-top: auto;
}

/* ============================================
   分页
   ============================================ */
.pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: var(--spacing-xs);
    margin-top: var(--spacing-2xl);
}

.pagination-btn {
    min-width: 44px;
    height: 44px;
    padding: 0 var(--spacing-sm);
    background-color: var(--bg-card);
    border: 1px solid var(--border-light);
    border-radius: var(--radius);
    font-size: var(--font-sm);
    font-weight: 500;
    color: var(--text-secondary);
    cursor: pointer;
    transition: all var(--transition);
}

.pagination-btn:hover:not(.disabled) {
    background-color: var(--primary-50);
    border-color: var(--primary);
    color: var(--primary);
}

[data-theme="dark"] .pagination-btn:hover:not(.disabled) {
    background-color: var(--primary-900);
}

.pagination-btn.active {
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    border-color: var(--primary);
    color: white;
}

.pagination-btn.disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination-ellipsis {
    padding: 0 var(--spacing-sm);
    color: var(--text-muted);
}

/* ============================================
   分类列表
   ============================================ */
.categories-list {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-lg);
}

.category-item {
    background-color: var(--bg-card);
    border-radius: var(--radius-xl);
    border: 1px solid var(--border-light);
    overflow: hidden;
    transition: all var(--transition);
}

.category-item:hover {
    box-shadow: var(--shadow-lg);
    border-color: var(--primary-200);
}

.category-item-header {
    display: flex;
    align-items: center;
    gap: var(--spacing-lg);
    padding: var(--spacing-xl);
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
}

[data-theme="dark"] .category-item-header {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
}

.category-icon-lg {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    border-radius: var(--radius-xl);
    color: white;
    font-size: 2rem;
    flex-shrink: 0;
}

.category-item-info {
    flex: 1;
}

.category-item-title {
    font-size: var(--font-2xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-xs);
}

.category-item-description {
    font-size: var(--font-sm);
    color: var(--text-secondary);
}

.category-item-stats .stat {
    padding: var(--spacing-sm) var(--spacing-md);
    background-color: var(--bg-card);
    border-radius: var(--radius-full);
    font-size: var(--font-sm);
    font-weight: 600;
    color: var(--primary);
}

.category-item-articles {
    padding: var(--spacing-lg) var(--spacing-xl);
    display: grid;
    gap: var(--spacing-sm);
}

.mini-article {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--spacing-md);
    border-radius: var(--radius);
    text-decoration: none;
    color: var(--text-primary);
    transition: all var(--transition);
}

.mini-article:hover {
    background-color: var(--bg-hover);
    padding-left: var(--spacing-lg);
}

.mini-article-title {
    font-size: var(--font-sm);
    font-weight: 500;
}

.mini-article-date {
    font-size: var(--font-xs);
    color: var(--text-muted);
}

.mini-article.more-link {
    color: var(--primary);
    font-weight: 600;
}

.mini-article.more-link:hover {
    background-color: var(--primary-50);
}

[data-theme="dark"] .mini-article.more-link:hover {
    background-color: var(--primary-900);
}

.mini-article.more-link i {
    transition: transform var(--transition);
}

.mini-article.more-link:hover i {
    transform: translateX(4px);
}

/* ============================================
   关于页面 - Hero
   ============================================ */
.hero-about {
    min-height: auto;
    padding: 140px 0 var(--spacing-2xl);
}

.hero-about-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
}

.hero-about-avatar {
    position: relative;
    margin-bottom: var(--spacing-xl);
}

.avatar-frame {
    position: relative;
    width: 150px;
    height: 150px;
}

.avatar-placeholder {
    width: 100%;
    height: 100%;
    border-radius: var(--radius-full);
    overflow: hidden;
    border: 4px solid white;
    box-shadow: var(--shadow-xl);
}

[data-theme="dark"] .avatar-placeholder {
    border-color: var(--bg-secondary);
}

.avatar-placeholder svg {
    width: 100%;
    height: 100%;
}

.avatar-status {
    position: absolute;
    bottom: 8px;
    right: 8px;
    width: 20px;
    height: 20px;
    background-color: var(--accent);
    border: 3px solid white;
    border-radius: var(--radius-full);
}

[data-theme="dark"] .avatar-status {
    border-color: var(--bg-secondary);
}

.hero-about-name {
    font-size: var(--font-5xl);
    font-weight: 800;
    color: var(--text-primary);
    margin-bottom: var(--spacing-sm);
}

.hero-about-title {
    font-size: var(--font-xl);
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
}

.hero-about-bio {
    max-width: 600px;
    font-size: var(--font-lg);
    color: var(--text-secondary);
    margin-bottom: var(--spacing-xl);
    line-height: 1.8;
}

.hero-about-social {
    display: flex;
    gap: var(--spacing-sm);
    margin-bottom: var(--spacing-xl);
}

.social-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    background-color: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    color: var(--text-secondary);
    font-size: var(--font-lg);
    text-decoration: none;
    transition: all var(--transition);
}

.social-btn:hover {
    background-color: var(--primary);
    border-color: var(--primary);
    color: white;
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

.hero-about-cta {
    display: flex;
    gap: var(--spacing-md);
}

/* ============================================
   技能区域
   ============================================ */
.skills-container {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-xl);
}

.skill-category {
    background-color: var(--bg-card);
    border-radius: var(--radius-xl);
    padding: var(--spacing-xl);
    border: 1px solid var(--border-light);
}

.skill-category-title {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    font-size: var(--font-xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-lg);
}

.skill-category-title i {
    color: var(--primary);
}

.skills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-lg);
}

.skill-item {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.skill-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    border-radius: var(--radius-lg);
    color: var(--primary);
    font-size: 1.5rem;
}

[data-theme="dark"] .skill-icon {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
}

.skill-name {
    font-size: var(--font-sm);
    font-weight: 600;
    color: var(--text-primary);
}

.skill-level {
    height: 6px;
    background-color: var(--bg-tertiary);
    border-radius: var(--radius-full);
    overflow: hidden;
}

.skill-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--primary), var(--primary-dark));
    border-radius: var(--radius-full);
    transition: width 1s ease-out;
}

/* ============================================
   时间线
   ============================================ */
.timeline {
    position: relative;
    max-width: 800px;
    margin: 0 auto;
}

.timeline::before {
    content: '''';
    position: absolute;
    left: 24px;
    top: 0;
    bottom: 0;
    width: 2px;
    background: linear-gradient(180deg, var(--primary), var(--primary-light));
}

.timeline-item {
    position: relative;
    padding-left: 60px;
    padding-bottom: var(--spacing-xl);
}

.timeline-marker {
    position: absolute;
    left: 12px;
    top: 0;
    width: 26px;
    height: 26px;
    background: linear-gradient(135deg, var(--primary), var(--primary-dark));
    border: 4px solid var(--bg-primary);
    border-radius: var(--radius-full);
    box-shadow: var(--shadow-md);
}

.timeline-content {
    background-color: var(--bg-card);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    border: 1px solid var(--border-light);
    transition: all var(--transition);
}

.timeline-content:hover {
    box-shadow: var(--shadow-lg);
    transform: translateX(4px);
}

.timeline-date {
    display: inline-block;
    padding: var(--spacing-xs) var(--spacing-sm);
    background: linear-gradient(135deg, var(--primary-50), var(--primary-100));
    color: var(--primary-600);
    font-size: var(--font-xs);
    font-weight: 600;
    border-radius: var(--radius-sm);
    margin-bottom: var(--spacing-sm);
}

[data-theme="dark"] .timeline-date {
    background: linear-gradient(135deg, var(--primary-900), var(--primary-800));
    color: var(--primary-200);
}

.timeline-title {
    font-size: var(--font-xl);
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: var(--spacing-xs);
}

.timeline-company {
    font-size: var(--font-sm);
    color: var(--primary);
    margin-bottom: var(--spacing-sm);
}

.timeline-description {
    font-size: var(--font-sm);
    color: var(--text-secondary);
    line-height: 1.7;
    margin-bottom: var(--spacing-md);
}

.timeline-tags {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-xs);
}

/* ============================================
